 * Serializes a request body for use in a Swagger "try it out" request.
 *
 * Swagger UI hands us a variety of body types depending on the operation's
 * media type. Bruno's proxy only knows how to forward string payloads, so we
 * normalize the ones we can and throw a helpful error for the ones we can't.
 */

export const UNSUPPORTED_BODY_TYPE_CODE = 'UNSUPPORTED_BODY_TYPE';

export const UNSUPPORTED_BODY_MESSAGE = (bodyTypeName) =>
  `${bodyTypeName} isn't supported in Bruno yet. Supported request bodies are JSON, URL-encoded forms, plain text.`;

const unsupportedBodyError = (bodyType, message) => {
  const error = new TypeError(message ?? UNSUPPORTED_BODY_MESSAGE(bodyType));
  error.code = UNSUPPORTED_BODY_TYPE_CODE;
  error.bodyType = bodyType;
  return error;
};

const serializeBody = (body) => {
  if (body === null || body === undefined) {
    return undefined;
  }

  if (typeof body === 'string') {
    return body;
  }

  if (typeof URLSearchParams !== 'undefined' && body instanceof URLSearchParams) {
    return body.toString();
  }

  if (typeof FormData !== 'undefined' && body instanceof FormData) {
    throw unsupportedBodyError(
      'FormData',
      'Multipart form data isn\'t supported in the API spec panel yet. Create a Bruno request to send multipart form data.'
    );
  }

  if (typeof File !== 'undefined' && body instanceof File) {
    throw unsupportedBodyError(
      'File',
      'File upload isn\'t supported in the API spec panel yet. Create a Bruno request to upload files.'
    );
  }

  if (typeof Blob !== 'undefined' && body instanceof Blob) {
    throw unsupportedBodyError(
      'Blob',
      'Binary file upload isn\'t supported in the API spec panel yet. Create a Bruno request to send binary data.'
    );
  }

  if (typeof ArrayBuffer !== 'undefined' && body instanceof ArrayBuffer) {
    throw unsupportedBodyError(
      'ArrayBuffer',
      'Binary data isn\'t supported in the API spec panel yet. Create a Bruno request to send binary data.'
    );
  }

  if (typeof ArrayBuffer !== 'undefined' && ArrayBuffer.isView(body)) {
    const bodyType = body.constructor?.name ?? 'TypedArray';
    throw unsupportedBodyError(
      bodyType,
      'Binary data isn\'t supported in the API spec panel yet. Create a Bruno request to send binary data.'
    );
  }

  const bodyType = body.constructor?.name ?? typeof body;
  throw unsupportedBodyError(bodyType);
};

export default serializeBody;
